('04285a8c-a4ff-5e4c-8bdd-0bd070a663b5'::uuid,'est2','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','numeric','"Q2. |x + 20| = 8. What is one possible solution to the given equation?"'::jsonb,'[]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"panda.md","source_sha256":"e120378a8127836a41962876a763889bbb1df92d70c90242206130acfa43e008","source_question_id":"CP-c04-02","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"−28 or −12"'::jsonb,'"Source-keyed answer from panda.md (CP-c04-02)."'::jsonb),
